/* ── Skip Link ── */
.skip-link{position:absolute;top:-100%;left:16px;background:#0072F5;color:#fff;padding:8px 16px;border-radius:0 0 6px 6px;z-index:1000;font-weight:500;transition:top .2s}
.skip-link:focus{top:0}

/* ── Header ── */
.site-header{position:sticky;top:0;z-index:100;background:#FAFAFA;border-bottom:1px solid #E5E7EB;backdrop-filter:blur(12px);background:rgba(250,250,250,.85)}
.header-inner{max-width:1280px;margin:0 auto;padding:0 24px;display:flex;align-items:center;height:60px;gap:32px}
.header-logo{font-size:20px;font-weight:700;color:#171717;white-space:nowrap;display:flex;align-items:center;gap:8px}
.header-logo svg{flex-shrink:0}
.header-logo span{letter-spacing:-0.02em}

/* Nav */
.main-nav{display:flex;align-items:center;gap:4px;flex:1}
.nav-item{position:relative}
.nav-link{display:flex;align-items:center;gap:4px;padding:8px 12px;font-size:14px;font-weight:500;color:#4B5563;border-radius:8px;transition:color .15s,background .15s}
.nav-link:hover,.nav-link.active{color:#171717;background:#F3F4F6}
.nav-link svg.chevron{width:14px;height:14px;transition:transform .2s}
.nav-item.open .nav-link svg.chevron{transform:rotate(180deg)}

.header-actions{display:flex;align-items:center;gap:12px;margin-left:auto}
.header-actions .btn-ghost{font-size:14px;font-weight:500;color:#4B5563;padding:8px 14px;border-radius:8px;transition:color .15s,background .15s}
.header-actions .btn-ghost:hover{color:#171717;background:#F3F4F6}
.header-actions .btn-primary{font-size:14px;font-weight:600;color:#fff;background:#0072F5;padding:8px 18px;border-radius:8px;transition:background .15s}
.header-actions .btn-primary:hover{background:#0056CC}

/* ── Mega Menu ── */
.mega-menu{position:absolute;top:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#fff;border:1px solid #E5E7EB;border-radius:14px;box-shadow:0 20px 50px rgba(0,0,0,.08);padding:28px 32px;display:none;min-width:640px;z-index:200}
.nav-item.open .mega-menu{display:flex;gap:40px}
.mega-menu-col{flex:1}
.mega-menu-col h4{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#9CA3AF;margin-bottom:12px}
.mega-menu-col a{display:flex;flex-direction:column;padding:8px 10px;border-radius:8px;margin:0 -10px;transition:background .15s}
.mega-menu-col a:hover{background:#F9FAFB}
.mega-menu-col a .title{font-size:14px;font-weight:600;color:#171717;margin-bottom:1px}
.mega-menu-col a .desc{font-size:12px;color:#6B7280;line-height:1.4}

/* ── Page Wrapper ── */
.page-wrap{max-width:1280px;margin:0 auto;padding:0 24px}

/* ── Hero / Category Section ── */
