.blog-hero p{font-size:18px;color:#6B7280;max-width:640px;line-height:1.5}

/* Category Filters */
.filter-bar{display:flex;align-items:center;gap:8px;padding-bottom:40px;flex-wrap:wrap}
.category-pills{display:flex;gap:8px;flex-wrap:wrap;flex:1}
.category-pill{font-size:13px;font-weight:500;padding:7px 16px;border-radius:100px;border:1px solid #D1D5DB;color:#4B5563;background:#fff;transition:all .15s;white-space:nowrap}
.category-pill:hover{border-color:#9CA3AF;color:#171717}
.category-pill.active{background:#171717;color:#fff;border-color:#171717}
.search-wrap{position:relative;width:260px;flex-shrink:0}
.search-wrap svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:#9CA3AF;pointer-events:none}
.search-input{width:100%;font-size:14px;padding:8px 14px 8px 36px;border:1px solid #D1D5DB;border-radius:100px;background:#fff;color:#171717;transition:border-color .15s}
.search-input::placeholder{color:#9CA3AF}
.search-input:focus{outline:none;border-color:#0072F5}

/* ── Featured Articles ── */
.featured-section{padding-bottom:48px}
.featured-label{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#9CA3AF;margin-bottom:16px}
.featured-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px}

.featured-card{background:#fff;border:1px solid #E5E7EB;border-radius:14px;overflow:hidden;transition:box-shadow .2s,border-color .2s;display:flex;flex-direction:column}
.featured-card:hover{border-color:#D1D5DB;box-shadow:0 4px 20px rgba(0,0,0,.04)}
.featured-card:first-child{grid-column:1 / -1;display:grid;grid-template-columns:1fr 1fr;gap:0}
.featured-card:first-child .fc-content{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}
.featured-card:first-child .fc-stats{background:#F9FAFB;padding:32px 36px;display:flex;flex-direction:column;justify-content:center;border-left:1px solid #E5E7EB}

.fc-content{padding:24px 28px;flex:1;display:flex;flex-direction:column}
.fc-meta{display:flex;align-items:center;gap:12px;margin-bottom:12px}
.fc-category{font-size:12px;font-weight:600;color:#0072F5;background:rgba(0,114,245,.08);padding:3px 10px;border-radius:100px}
.fc-date{font-size:13px;color:#9CA3AF}
.fc-title{font-size:20px;font-weight:700;line-height:1.25;color:#171717;margin-bottom:10px;letter-spacing:-0.01em}
.featured-card:first-child .fc-title{font-size:26px;line-height:1.2}
.fc-excerpt{font-size:14px;color:#6B7280;line-height:1.55;flex:1}
.featured-card:first-child .fc-excerpt{font-size:15px}
.fc-author{display:flex;align-items:center;gap:10px;margin-top:16px;padding-top:16px;border-top:1px solid #F3F4F6}
.fc-avatar{width:32px;height:32px;border-radius:50%;background:#E5E7EB;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:600;color:#4B5563;flex-shrink:0}
.fc-author-name{font-size:13px;font-weight:600;color:#171717}

/* Stats block */
.stats-heading{font-size:13px;font-weight:600;color:#0072F5;text-transform:uppercase;letter-spacing:.04em;margin-bottom:20px}
.stat-item{margin-bottom:16px}
.stat-value{font-size:32px;font-weight:800;letter-spacing:-0.02em;color:#171717;line-height:1}
.stat-label{font-size:13px;color:#6B7280;margin-top:4px;line-height:1.4}
.stat-note{font-size:12px;color:#9CA3AF;margin-top:16px;line-height:1.5}
.stat-note strong{color:#171717}

/* ── Latest News ── */
.news-section{padding-bottom:48px}
.news-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}
.news-header h2{font-size:24px;font-weight:700;letter-spacing:-0.02em}
.news-count{font-size:14px;color:#9CA3AF}
.news-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px}

.news-card{background:#fff;border:1px solid #E5E7EB;border-radius:14px;padding:24px 28px;transition:box-shadow .2s,border-color .2s;display:flex;flex-direction:column}
.news-card:hover{border-color:#D1D5DB;box-shadow:0 4px 20px rgba(0,0,0,.04)}
.news-card .fc-meta{margin-bottom:10px}
.news-card .fc-title{font-size:18px}
.news-card .fc-excerpt{font-size:13px;margin-bottom:4px}

/* No results */
.no-results{display:none;text-align:center;padding:48px 24px}
.no-results.visible{display:block}
.no-results-icon{font-size:40px;margin-bottom:12px;opacity:.5}
.no-results h3{font-size:18px;font-weight:600;color:#171717;margin-bottom:6px}
