.footer-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:32px}
.footer-col h4{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:#6B7280;margin-bottom:14px}
.footer-col a{display:block;font-size:13px;color:#9CA3AF;padding:4px 0;transition:color .15s}
.footer-col a:hover{color:#fff}

.footer-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:48px;padding-top:24px;border-top:1px solid rgba(255,255,255,.08);flex-wrap:wrap;gap:12px}
.footer-bottom .logo-text{font-size:14px;font-weight:600;color:#fff}
.footer-bottom .copyright{font-size:12px;color:#6B7280}
.footer-status{display:flex;align-items:center;gap:8px;font-size:13px;color:#9CA3AF}
.status-dot{width:7px;height:7px;border-radius:50%;background:#22C55E;flex-shrink:0}

/* ── Animations ── */
@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.news-card{animation:fadeIn .3s ease-out}
@media(prefers-reduced-motion:reduce){*{animation-duration:.01ms!important;transition-duration:.01ms!important}}

/* ── Hamburger (mobile) ── */
.hamburger{display:none;flex-direction:column;gap:5px;padding:8px;cursor:pointer;border-radius:6px}
.hamburger span{width:20px;height:2px;background:#171717;border-radius:1px;transition:transform .2s,opacity .2s}
.mobile-nav{display:none;position:fixed;top:60px;left:0;right:0;bottom:0;background:#fff;z-index:99;padding:24px;overflow-y:auto;flex-direction:column;gap:4px}
.mobile-nav.open{display:flex}
.mobile-nav .nav-link{font-size:15px;padding:12px;border-radius:8px}
.mobile-nav .mega-menu{position:static;transform:none;box-shadow:none;border:none;padding:0 0 0 16px;min-width:0;margin-bottom:8px}
.mobile-nav .nav-item.open .mega-menu{display:flex;flex-direction:column;gap:16px}
.mobile-nav .mega-menu-col a{flex-direction:column}
.mobile-nav .mega-menu-col a .desc{display:none}

/* ── Responsive ── */
@media(max-width:1023px){
  .featured-grid{grid-template-columns:1fr 1fr}
  .featured-card:first-child{grid-column:1 / -1;grid-template-columns:1fr}
  .featured-card:first-child .fc-stats{border-left:none;border-top:1px solid #E5E7EB}
  .news-grid{grid-template-columns:1fr 1fr}
  .footer-grid{grid-template-columns:repeat(3,1fr)}
  .main-nav .nav-link span.nav-label{display:none}
  .main-nav .nav-link{padding:8px}
  .main-nav{gap:0}
}

@media(max-width:767px){
  .header-inner{height:54px;padding:0 16px;gap:12px}
  .header-logo{font-size:17px}
  .main-nav{display:none}
  .header-actions .btn-ghost{display:none}
  .header-actions .btn-primary{font-size:13px;padding:7px 14px}
  .hamburger{display:flex}
  .blog-hero h1{font-size:28px}
  .blog-hero p{font-size:15px}
  .filter-bar{flex-direction:column;align-items:stretch;gap:12px}
  .search-wrap{width:100%}
  .featured-grid{grid-template-columns:1fr}
  .featured-card:first-child .fc-content,.featured-card:first-child .fc-stats{padding:24px}
  .fc-content{padding:20px 22px}
  .fc-title{font-size:18px}
  .featured-card:first-child .fc-title{font-size:22px}
  .news-grid{grid-template-columns:1fr}
  .cta-banner{flex-direction:column;padding:32px 24px;gap:28px;text-align:center}
  .cta-content h2{font-size:22px}
  .cta-actions{justify-content:center}
  .cta-enterprise{width:100%;text-align:center}
  .cta-enterprise p{max-width:none}
  .footer-grid{grid-template-columns:1fr 1fr;gap:24px}
}

@media(max-width:374px){
  .category-pills{gap:6px}
  .category-pill{font-size:12px;padding:6px 12px}
  .footer-grid{grid-template-columns:1fr}
}
</style>
