const POSTS_PER_PAGE = 6;
let visibleCount = POSTS_PER_PAGE;
let activeCategory = 'all';
let searchQuery = '';

// ── Render ──
function getFilteredPosts() {
  return allPosts.filter(p => {
    const catMatch = activeCategory === 'all' || p.category === activeCategory;
    const searchMatch = !searchQuery ||
      p.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.excerpt.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.author.toLowerCase().includes(searchQuery.toLowerCase());
    return catMatch && searchMatch;
  });
}

function renderPost(p) {
  return `<article class="news-card" data-category="${p.category}">
    <div class="fc-meta">
      <span class="fc-category">${categoryLabel(p.category)}</span>
      <span class="fc-date">${p.date}</span>
    </div>
    <h3 class="fc-title">${p.title}</h3>
    <p class="fc-excerpt">${p.excerpt}</p>
