      <div class="fc-avatar" aria-hidden="true">${p.initials}</div>
      <span class="fc-author-name">${p.author}</span>
    </div>
  </article>`;
}

function categoryLabel(cat) {
  const map = {
    'engineering': 'Engineering',
    'community': 'Community',
    'company-news': 'Company News',
    'customers': 'Customers',
    'v0': 'v0',
    'security': 'Security',
    'changelog': 'Changelog',
    'press': 'Press'
  };
  return map[cat] || cat;
}

function updateGrid() {
  const filtered = getFilteredPosts();
  const visible = filtered.slice(0, visibleCount);
  const grid = document.getElementById('news-grid');
  const noResults = document.getElementById('no-results');
  const showMoreWrap = document.getElementById('show-more-wrap');
  const countEl = document.getElementById('news-count');

  grid.innerHTML = visible.map(renderPost).join('');
  countEl.textContent = `${filtered.length} posts`;

  if (filtered.length === 0) {
    noResults.classList.add('visible');
    showMoreWrap.style.display = 'none';
  } else {
    noResults.classList.remove('visible');
    showMoreWrap.style.display = visibleCount < filtered.length ? '' : 'none';
  }

  document.getElementById('btn-show-more').disabled = visibleCount >= filtered.length;
}

function showMore() {
  visibleCount += POSTS_PER_PAGE;
  updateGrid();
}

// ── Category Filtering ──
document.getElementById('category-pills').addEventListener('click', function(e) {
  const pill = e.target.closest('.category-pill');
  if (!pill) return;

  document.querySelectorAll('.category-pill').forEach(p => p.classList.remove('active'));
  pill.classList.add('active');
  activeCategory = pill.dataset.category;
  visibleCount = POSTS_PER_PAGE;
  updateGrid();
});

// ── Search ──
let searchDebounce;
document.getElementById('search-input').addEventListener('input', function(e) {
  clearTimeout(searchDebounce);
  searchDebounce = setTimeout(() => {
    searchQuery = e.target.value.trim();
    visibleCount = POSTS_PER_PAGE;
    updateGrid();
  }, 200);
});

// ── Dropdowns ──
function closeAllDropdowns(except) {
  document.querySelectorAll('.nav-item.open').forEach(item => {
    if (item.id !== except) {
      item.classList.remove('open');
      item.querySelector('button[aria-expanded]')?.setAttribute('aria-expanded', 'false');
    }
  });
}

function toggleDropdown(name) {
  const item = document.getElementById('nav-' + name);
  const btn = item.querySelector('button[aria-expanded]');
  const isOpen = item.classList.contains('open');
  closeAllDropdowns('nav-' + name);
  if (isOpen) {
    item.classList.remove('open');
    btn.setAttribute('aria-expanded', 'false');
  } else {
    item.classList.add('open');
    btn.setAttribute('aria-expanded', 'true');
  }
}

// Close dropdowns on outside click
document.addEventListener('click', function(e) {
  if (!e.target.closest('.nav-item')) closeAllDropdowns();
});

// Close dropdowns on Escape
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') closeAllDropdowns();
});

// ── Mobile Nav ──
function toggleMobileNav() {
  const nav = document.getElementById('mobile-nav');
  nav.classList.toggle('open');
  document.querySelector('.hamburger').setAttribute('aria-expanded', nav.classList.contains('open') ? 'true' : 'false');
}

function toggleMobileDropdown(id) {
  const el = document.getElementById(id);
  const btn = el.previousElementSibling;
  const isOpen = el.style.display === 'flex';
  el.style.display = isOpen ? 'none' : 'flex';
  btn.setAttribute('aria-expanded', !isOpen);
}

// ── Init ──
updateGrid();
</script>
